    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check required edge
    assert (4, 8) in edges or (8, 4) in edges, "Missing required edge (4,8)"

    # Check no triangles
    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > v and w in adj[u]:
                        print(f"Triangle found: {u}-{v}-{w}")
                        return False

    # Check no 4-cycles
    for a in range(n):
        for b in adj[a]:
            if b > a:
                for c in adj[b]:
                    if c > b and c != a:
                        for d in adj[c]:
                            if d > c and d != b and d in adj[a]:
                                print(f"4-cycle found: {a}-{b}-{c}-{d}")
                                return False

    # Check 5-colorable
    colors = [-1] * n
    def backtrack(v):
        if v == n:
            return True
        for c in range(5):
